-- ============================================================
-- Единая база вопросов — актуальный полный срез таблицы
-- public.questions (1000 вопросов, 10 категорий по 100).
--
-- Второе поколение базы (было 500/10/50): полный аудит + расширение
-- по каждой категории — см. 037_question_bank_v2_cleanup.sql для
-- истории удалений. Каждый вопрос несёт уровень сложности
-- (difficulty: easy/medium/hard, см. 036_question_difficulty.sql) —
-- пока никакой RPC его не использует, это задел на будущее.
--
-- Идемпотентен, но теперь через ON CONFLICT ... DO UPDATE, а не
-- DO NOTHING: повторный прогон не просто безопасен, а ещё и
-- подчищает существующие строки (options/category/difficulty) до
-- состояния, описанного здесь — этот файл первичен, а не база.
-- Массивы вариантов задаются через ARRAY[...] с обычным SQL-
-- экранированием кавычек, а не через литерал '{...}'::text[] (как
-- было раньше) — надёжнее генерировать программно, семантически то
-- же самое.
-- ============================================================

on conflict (question) do update set
  options              = excluded.options,
  correct_option_index = excluded.correct_option_index,
  category              = excluded.category,
  difficulty            = excluded.difficulty;
